package vn.covie.cart.api; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import vn.covie.cart.api.dto.*; import vn.covie.cart.application.CartMutationService; import vn.covie.shared.concurrency.VersionPrecondition;
@RestController @RequestMapping("/api/v1/me/carts/{cartId}/items")public class CartMutationController{private final CartMutationService service;public CartMutationController(CartMutationService service){this.service=service;}@PatchMapping("/{itemId}")public ResponseEntity<CartResponse> update(@PathVariable UUID cartId,@PathVariable UUID itemId,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String ifMatch,@RequestBody UpdateCartItemRequest req){var r=service.update(cartId,itemId,ifMatch,req);return ResponseEntity.ok().eTag(VersionPrecondition.format(r.version())).body(r);}@DeleteMapping("/{itemId}")public ResponseEntity<Void> delete(@PathVariable UUID cartId,@PathVariable UUID itemId,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String ifMatch){service.remove(cartId,itemId,ifMatch);return ResponseEntity.noContent().build();}}
